"""Finite causal shell seed generated by a local residue alphabet and code.

For a codeword c and local alphabet with minimum representative grade g(a) and
multiplicity mu(a), the minimum lift contributes

    M(c) t^G(c) = product_i mu(c_i) * t^(sum_i g(c_i)).

Adding N copies of the local zero-sector primitive event family gives the finite
integer polynomial

    P(t)=N*r0*t^g0 + sum_(c!=0) M(c)t^G(c).

The smallest exponent with nonzero coefficient is the primitive global grade;
its coefficient is the primitive event count.  This is a minimum-lift shell seed,
not the full lattice theta series.  Traditional complete-weight-enumerator
substitution is a computational shadow of the slotwise factorization.
"""

from __future__ import annotations

from collections import Counter

from .causal_local_alphabet_code import (
    Codeword,
    LocalResidueAlphabet,
    codeword_grade,
    codeword_minimum_lift_multiplicity,
)


def causal_shell_seed(
    codewords: tuple[Codeword, ...],
    alphabet: LocalResidueAlphabet,
) -> dict[int, int]:
    alphabet.validate()
    if not codewords:
        raise ValueError("codeword family must be non-empty")
    length = len(codewords[0])
    if length == 0 or any(len(word) != length for word in codewords):
        raise ValueError("codewords must have equal positive length")
    coefficients: Counter[int] = Counter()
    coefficients[alphabet.zero_sector_primitive_grade] += (
        length * alphabet.zero_sector_primitive_multiplicity
    )
    for word in codewords:
        if all(symbol == alphabet.zero_symbol for symbol in word):
            continue
        coefficients[codeword_grade(word, alphabet)] += (
            codeword_minimum_lift_multiplicity(word, alphabet)
        )
    return dict(sorted(coefficients.items()))


def primitive_shell_from_seed(seed: dict[int, int]) -> tuple[int, int]:
    if not seed or any(grade < 0 or count <= 0 for grade, count in seed.items()):
        raise ValueError("seed must be a non-empty positive integer grade inventory")
    grade = min(seed)
    return grade, seed[grade]


def seed_valuation(seed: dict[int, int]) -> int:
    return primitive_shell_from_seed(seed)[0]
